import{_ as a,a as s,b as t,c as i,d as r,e as n,f as p,g as o,h as l,i as h,j as d,k as c,l as m,m as g,n as u,o as k,p as v,q as _,r as b,s as y,t as x}from"./chunks/image-28.lsL7eUrl.js";import{_ as f,o as F,c as C,ae as S}from"./chunks/framework.DJIAqD5B.js";const L=JSON.parse('{"title":"Server / Windows","description":"","frontmatter":{},"headers":[],"relativePath":"en/user-guide/install/server.md","filePath":"en/user-guide/install/server.md"}'),E={name:"en/user-guide/install/server.md"};function w(q,e,X,D,M,B){return F(),C("div",null,[...e[0]||(e[0]=[S('<h1 id="server-windows" tabindex="-1">Server / Windows <a class="header-anchor" href="#server-windows" aria-label="Permalink to &quot;Server / Windows&quot;">​</a></h1><h2 id="_1-download-the-server-tools" tabindex="-1">1. Download the server tools <a class="header-anchor" href="#_1-download-the-server-tools" aria-label="Permalink to &quot;1. Download the server tools&quot;">​</a></h2><p>Setting up a server directly from the command line is possible, but it is usually more complicated than necessary.</p><p>We recommend using MSLX Manager to download and manage the server.</p><p>MSLX Manager download page:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mslx.mslmc.cn/</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><h2 id="_2-mslx-manager-requires-the-net-10-0-sdk" tabindex="-1">2. MSLX Manager requires the .NET 10.0 SDK <a class="header-anchor" href="#_2-mslx-manager-requires-the-net-10-0-sdk" aria-label="Permalink to &quot;2. MSLX Manager requires the .NET 10.0 SDK&quot;">​</a></h2></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://dotnet.microsoft.com/download/dotnet/10.0</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Download the 64-bit .NET 10.0 SDK, not another edition.</p></div><p><img src="'+a+'" alt=".NET download"></p><p>Then download MSLX Manager.</p><p><img src="'+s+'" alt="MSLX page"></p><p>Click download.</p><p><img src="'+t+'" alt="Download button"></p><h2 id="_3-extract-the-package" tabindex="-1">3. Extract the package <a class="header-anchor" href="#_3-extract-the-package" aria-label="Permalink to &quot;3. Extract the package&quot;">​</a></h2><p>After downloading, you will get a file like this:</p><p><img src="'+i+'" alt="Downloaded file"></p><p>Extract it into the directory where you want to install the server tools. You can choose any folder name.</p><p><img src="'+r+'" alt="Extract folder"></p><p>The extracted result should look similar to this:</p><p><img src="'+n+`" alt="Extract result"></p><h2 id="_4-start-mslx-daemon-exe" tabindex="-1">4. Start <code>MSLX-Daemon.exe</code> <a class="header-anchor" href="#_4-start-mslx-daemon-exe" aria-label="Permalink to &quot;4. Start \`MSLX-Daemon.exe\`&quot;">​</a></h2><p>Open the program folder and run <code>MSLX-Daemon.exe</code>.</p><p>You should see output similar to this:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Program[0]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">      MSLX.Daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> starting...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> listening</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> at:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:1027</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Browser URL: http://localhost:1027</span></span></code></pre></div><p>Open that address in your browser and log in to MSLX Manager.</p><p><img src="`+p+'" alt="Login page"></p><h2 id="_5-configure-the-server" tabindex="-1">5. Configure the server <a class="header-anchor" href="#_5-configure-the-server" aria-label="Permalink to &quot;5. Configure the server&quot;">​</a></h2><p>Go to the configuration page.</p><p><img src="'+o+'" alt="Config page"></p><p>Click server management and create a server.</p><p><img src="'+l+'" alt="Server management"></p><p>Choose a path and a server name, then continue.</p><p><img src="'+h+'" alt="Path and name"></p><p>Select the required Java version exactly as prompted.</p><p><img src="'+d+'" alt="Java selection"></p><p>Choose the server core you want.</p><p><img src="'+c+'" alt="Core selector"></p><p><code>xiaozi craft</code> requires Fabric Server. Select the version that matches your game version.</p><p><img src="'+m+'" alt="Fabric server"></p><p>Continue to the next step.</p><p><img src="'+g+'" alt="Next step"></p><p>Configure memory:</p><p><img src="'+u+`" alt="Memory config"></p><p>Reference values:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-Xms6G -Xmx6G     // 1-5 players</span></span>
<span class="line"><span>-Xms12G -Xmx12G   // 10-20 players</span></span>
<span class="line"><span>-Xms24G -Xmx24G   // 20-40 players</span></span>
<span class="line"><span>-Xms32G -Xmx32G   // 40-80 players</span></span>
<span class="line"><span>-Xms64G -Xmx64G   // 80-160 players</span></span>
<span class="line"><span>-Xms128G -Xmx128G // 160-320 players</span></span></code></pre></div><p>You can leave the JVM arguments field empty for now and configure it later.</p><h2 id="_6-create-and-start-the-server" tabindex="-1">6. Create and start the server <a class="header-anchor" href="#_6-create-and-start-the-server" aria-label="Permalink to &quot;6. Create and start the server&quot;">​</a></h2><p><img src="`+k+'" alt="Create server"></p><p>Go to the console:</p><p><img src="'+v+'" alt="Console"></p><p>Start the server:</p><p><img src="'+_+'" alt="Start server"></p><p>Accept the required agreement:</p><p><img src="'+b+`" alt="Accept EULA"></p><p>If you see output like this, the server has started successfully:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[22:24:37] [Server thread/INFO]: Done (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">4.166s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> For</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;help&quot;</span></span></code></pre></div><p>Stop the server before adding the modpack files.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In MSLX Manager, do not add a leading slash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stop</span></span></code></pre></div><p>You can also use the UI button:</p><p><img src="`+y+'" alt="Stop server"></p><h2 id="_7-add-the-xiaozi-craft-modpack-content" tabindex="-1">7. Add the <code>xiaozi craft</code> modpack content <a class="header-anchor" href="#_7-add-the-xiaozi-craft-modpack-content" aria-label="Permalink to &quot;7. Add the `xiaozi craft` modpack content&quot;">​</a></h2><p>In your local game instance, disable client-only or optimization mods before uploading files to the server. If a listed mod is missing, simply ignore it.</p><p>Then upload the remaining modpack files into the server <code>mods</code> folder and overwrite existing files when prompted.</p><p><img src="'+x+'" alt="Upload mods"></p><h2 id="done" tabindex="-1">Done <a class="header-anchor" href="#done" aria-label="Permalink to &quot;Done&quot;">​</a></h2><p>Start the server again and enjoy the game.</p>',67)])])}const P=f(E,[["render",w]]);export{L as __pageData,P as default};
